/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
/// This class is derived from standard <c>CustVendCreatePaymJournal_Cust</c> class to cater
/// for AMEX automatic payment proposal.
/// </summary>
class METAMEXCreatePaymJournal_Cust extends CustVendCreatePaymJournal_Cust
{

}

Method.Source:
/// <summary>
/// Class description
/// </summary>
/// <returns>Class description</returns>
public static ClassDescription description()
{
    return "@MET:METAMEXCustPaymProposalDesc";
}

/// <summary>
/// new instance of <c>METAMEXCreatePaymJournal_Cust</c>
/// </summary>
/// <returns><c>METAMEXCreatePaymJournal_Cust</c></returns>
public static METAMEXCreatePaymJournal_Cust construct()
{
    return new METAMEXCreatePaymJournal_Cust();
}

    /// <summary>
    /// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
    /// Non user interactive settings.
    /// </summary>
    protected void new()
    {
        super();

        this.showBatchTab(false);
        this.parmSkipProposalEditForm(NoYes::Yes);
        toDate = maxDate();
        balanceCheck = NoYes::Yes;
    }

/// <summary>
/// Main method to run the proposal
/// </summary>
/// <param name = "_args">Arguments requried to run the class</param>
 public static void main(Args _args)
 {
     METAMEXCreatePaymJournal_Cust::runPaymentProposal(_args);
 }

    /// <summary>
    /// Performs the payment proposal processing logic.
    /// </summary>
    /// <param name = "_args">A set of arguments for running payment proposal.</param>
    /// <returns>A <c>METAMEXCreatePaymJournal_Cust</c> object containing the results of the payment proposal.</returns>
    protected static METAMEXCreatePaymJournal_Cust runPaymentProposal(Args _args)
    {
        METAMEXCreatePaymJournal_Cust   createPaymJournal = METAMEXCreatePaymJournal_Cust::construct();
        LedgerJournalTable              ledgerJournalTable;

        if (_args.caller())
        {
            ledgerJournalTable = _args.caller().ledgerJournalTable();
        }
        if (ledgerJournalTable)
        {
            if (!createPaymJournal.isInBatch())
            {
                CustVendPaymProposalLine::deleteByJournalId(ledgerJournalTable.JournalNum);
            }
            createPaymJournal.getLast();
            createPaymJournal.parmLedgerJournalId(ledgerJournalTable.JournalNum);
        }

        createPaymJournal.metUpdateQueryAMEXProposal(_args);

        LedgerJournalName   journalName = ledgerJournalTable.ledgerJournalName();
        //preparing the proposal
        createPaymJournal.parmDefaultOffsetAccountType(LedgerJournalACTypeForPaymProposal::Bank);
        createPaymJournal.parmDefaultOffsetLedgerDimension(journalName.OffsetLedgerDimension);
        createPaymJournal.parmIncludeInvoicesFromOtherCompanies(NoYes::Yes);
        createPaymJournal.parmProposeSeparatePaymentPerCompany(NoYes::Yes);
        createPaymJournal.parmSkipProposalEditForm(NoYes::Yes);
        createPaymJournal.runOperation();
        createPaymJournal.paymProposal().parmIncludeInvoicesFromOtherCompanies(NoYes::Yes);

        //Transfering the proposal
        CustVendPaymProposalTransferToJournal transfer = CustVendPaymProposalTransferToJournal::constructForPaymProposal(createPaymJournal.paymProposal());
        transfer.transferProposal();

        return createPaymJournal;
    }

    /// <summary>
    /// Initializes <c>CustVendPaymProposalCalcPaym</c> from the dialog parameters.
    /// </summary>
    /// <returns>
    /// An instance of <c>CustVendPaymProposalCalcPaym</c>.
    /// </returns>
    protected CustVendPaymProposalCalcPaym initCustVendPaymProposalCalcPaym()
    {
        METAMEXCustVendPaymProposalCalcPaym metpaymProposalCalcPaym = METAMEXCustVendPaymProposalCalcPaym::construct(LedgerJournalTable::find(ledgerJournalId).JournalType);

        metpaymProposalCalcPaym.parmPaymDatePrinciple(paymProposalType);
        metpaymProposalCalcPaym.parmPaymWeekDayFixed(paymWeekDayFixed);
        metpaymProposalCalcPaym.parmPaymDateFixed(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()));
        metpaymProposalCalcPaym.parmMinimumPaymDate(earlyPaymDate);
        metpaymProposalCalcPaym.parmFromDate(fromDate);
        metpaymProposalCalcPaym.parmToDate(toDate);
        metpaymProposalCalcPaym.parmPaymCurrency(paymCurrency);
        metpaymProposalCalcPaym.parmPaymDate_IT(postingDate);
        metpaymProposalCalcPaym.parmPaymOnDateFixed_IT(useFutureDueDate);
        metpaymProposalCalcPaym.parmPostingDateOption_IT(postingDateOption_IT);

        return metpaymProposalCalcPaym;
    }

    /// <summary>
    /// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
    /// Query criteria is updated as per amex payment proposal.
    /// </summary>
    /// <param name = "_args">args</param>
    private void metUpdateQueryAMEXProposal(Args _args)
    {
        QueryBuildDataSource                qbdsCustTable, qbdsCustTrans, 
                                            qbdsMetCustTable, qbdsCustDispute;
        METAMEXCustPaymProposalContract     contract;

        if (_args.callerName() == classStr(METAMEXCustPaymProposalService))
        {
            contract = _args.caller().contract();
        }

        fromDate  = contract.parmFromDate();
        toDate    = contract.parmToDate();

        this.metAddSelectedCompaniesToDataSourceRange(str2con(contract.parmSelectedCompanies(), ';'));

        qbdsCustTable = this.queryRun().query().dataSourceTable(tableNum(CustTable));
        if (contract.parmPaymentRun() != CustAccountStatement::AMEXNone)
        {
            SysQuery::findOrCreateRange(qbdsCustTable, fieldNum(CustTable, AccountStatement)).value(QueryValue(contract.parmPaymentRun()));
        }

        if (contract.parmPaymMode())
        {
            SysQuery::findOrCreateRange(qbdsCustTable, fieldNum(CustTable, PaymMode)).value(QueryValue(contract.parmPaymMode()));
        }


        
        // Filter customers with blank credit card number
        qbdsMetCustTable = qbdsCustTable.addDataSource(tableNum(METCustTable));
        qbdsMetCustTable.addLink(fieldnum(CustTable,AccountNum),fieldnum(METCustTable,AccountNum));
        qbdsMetCustTable.joinMode(JoinMode::InnerJoin);
        qbdsMetCustTable.fetchMode(QueryFetchMode::One2One);
        qbdsMetCustTable.addRange(fieldnum(METCustTable, AmexCardNumberTxt)).value(SysQuery::valueNotEmptyString());

        qbdsCustTrans = this.queryRun().query().dataSourceTable(tableNum(CustTrans));

        SysQuery::findOrCreateRange(qbdsCustTrans, fieldNum(CustTrans, PaymMode)).value(SysQuery::valueNot(METConstants::TradeShow));
        SysQuery::findOrCreateRange(qbdsCustTrans, fieldNum(CustTrans, TransDate)).value(SysQuery::range(fromDate, toDate));

        qbdsCustDispute = qbdsCustTrans.addDataSource(tableNum(CustDispute));
        qbdsCustDispute.addLink(fieldnum(CustTrans, RecId),fieldnum(CustDispute,CustTrans));
        qbdsCustDispute.joinMode(JoinMode::NoExistsJoin);
        qbdsCustDispute.addRange(fieldnum(CustDispute, Status)).value(SysQuery::value(CustVendDisputeStatus::Disputed));

    }

    /// <summary>
    /// Apply date range on TransDate
    /// </summary>
    protected void updateQuery()
    {
        QueryBuildDataSource    qbdsCTO;

        super();

        if (LedgerJournalTable::find(ledgerJournalId).JournalType == LedgerJournalType::CustPayment)
        {
            qbdsCTO = queryCreatePayment.query().dataSourceTable(tableNum(CustTransOpen));

            qbdsCTO.clearRange(fieldNum(CustTransOpen, DueDate));

        }

    }

/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
/// Adds selected companies from the multi-select control to the company range of the
/// provided form data source query.
/// </summary>
/// <param name = "_companies">companies</param>
public void metAddSelectedCompaniesToDataSourceRange(container _companies)
{
    Query       query; 
    query = this.queryRun().query();
    query.allowCrossCompany(true);
    query.clearCompanyRange();
            
    for (int i = 1; i <= conLen(_companies); i++)
    {
        query.addCompanyRange(conPeek(_companies, i));
    }
}
